'use strict';
window.JustinSprites=(()=>{
 const photos={sideeye:[1100,350,950,1250],thumbsup:[540,460,490,760],sleepy:[0,0,1100,900],smug:[30,390,960,1400],bedhead:[20,110,175,250],announcement:[55,100,130,170],classroom:[65,92,75,110],neutral:[380,710,770,1300],hamster:null};
 const sources=new Map(),cache=new Map(),urls=new WeakMap();let version=0;
 function surface(){const c=document.createElement('canvas');c.width=384;c.height=600;return c}
 function load(id){if(sources.has(id))return sources.get(id);const entry={image:null,loading:true};sources.set(id,entry);const img=new Image();img.decoding='async';img.onload=()=>{const c=surface(),cx=c.getContext('2d'),box=photos[id];cx.save();if(box){cx.beginPath();cx.ellipse(192,300,188,296,0,0,Math.PI*2);cx.clip();const [x,y,bw,bh]=box;cx.drawImage(img,x,y,Math.min(bw,img.width-x),Math.min(bh,img.height-y),0,0,384,600)}else{const scale=Math.min(384/img.width,600/img.height);cx.drawImage(img,(384-img.width*scale)/2,(600-img.height*scale)/2,img.width*scale,img.height*scale)}cx.restore();entry.image=c;entry.loading=false;version++;img.src=''};img.onerror=()=>{entry.loading=false};img.src=(typeof ROOM_ASSETS!=='undefined'&&ROOM_ASSETS['assets/characters/'+id+'.png'])||'assets/characters/'+id+'.png';return entry}
 function get(skin){const id=skin?.id||'normal';if(Object.prototype.hasOwnProperty.call(photos,id)){const p=load(id);return p.image||cut}if(!faceReady)return cut;const key=id+':'+faceRevision;if(cache.has(key))return cache.get(key);const c=surface(),cx=c.getContext('2d');
  if(id==='miles'){
   cx.fillStyle='#11131a';cx.beginPath();cx.moveTo(80,380);cx.lineTo(20,590);cx.lineTo(364,590);cx.lineTo(304,380);cx.closePath();cx.fill();cx.strokeStyle='#ee273e';cx.lineWidth=13;cx.beginPath();cx.moveTo(65,585);cx.lineTo(110,405);cx.lineTo(274,405);cx.lineTo(320,585);cx.stroke();cx.fillStyle='#14151b';cx.beginPath();cx.ellipse(192,225,163,216,0,0,Math.PI*2);cx.fill();cx.strokeStyle='#ef273c';cx.lineWidth=8;cx.stroke();cx.save();cx.beginPath();cx.ellipse(192,218,133,202,0,0,Math.PI*2);cx.clip();cx.drawImage(cut,58,15,268,418);cx.restore();cx.fillStyle='#f12b45';cx.beginPath();cx.ellipse(192,495,15,23,0,0,Math.PI*2);cx.fill();cx.strokeStyle='#f12b45';cx.lineWidth=6;for(let i=0;i<4;i++){const y=477+i*11;cx.beginPath();cx.moveTo(184,y);cx.lineTo(149-i*3,y-18);cx.lineTo(132-i*3,y+12);cx.moveTo(200,y);cx.lineTo(235+i*3,y-18);cx.lineTo(252+i*3,y+12);cx.stroke()}
  }else if(id==='pixel'){const tiny=document.createElement('canvas');tiny.width=18;tiny.height=28;tiny.getContext('2d').drawImage(cut,0,0,18,28);cx.imageSmoothingEnabled=false;cx.drawImage(tiny,0,0,384,600)}else{cx.drawImage(cut,0,0,384,600);if(['fried','gold','lucky-gold','cursed'].includes(id)){const data=cx.getImageData(0,0,384,600),p=data.data;for(let i=0;i<p.length;i+=4){const r=p[i],g=p[i+1],b=p[i+2],l=.3*r+.59*g+.11*b;if(id==='fried'){p[i]=(r-110)*2.4+150;p[i+1]=(g-100)*2.1+100;p[i+2]=(b-100)*3+70}else if(id==='cursed'){p[i]=255-g;p[i+1]=255-b;p[i+2]=255-r}else{const shine=.9+.18*Math.sin((i/4%384)/384*8);p[i]=l*1.5*shine;p[i+1]=l*1.05*shine;p[i+2]=l*.22}}cx.putImageData(data,0,0)}if(id==='lucky-gold'){cx.strokeStyle='#e7b900';cx.lineWidth=6;cx.beginPath();cx.moveTo(90,100);cx.lineTo(65,35);cx.lineTo(140,70);cx.lineTo(192,10);cx.lineTo(244,70);cx.lineTo(319,35);cx.lineTo(294,100);cx.closePath();cx.fillStyle='#ffdf32';cx.fill();cx.stroke()}}
  if(cache.size>24)cache.clear();cache.set(key,c);return c;
 }
 function url(skin){const image=get(skin);if(!image?.width)return '';if(!urls.has(image))try{urls.set(image,image.toDataURL('image/png'))}catch{return ''}return urls.get(image)||''}
 return {get,url,get version(){return version}};
})();
